originalCss:
:root {
    --bg: #07111e;
    --bg-2: #0b1a2e;
    --bg-3: #10243d;
    --line: #1f3555;
    --line-2: #2b4670;
    --text: #e6eefc;
    --text-dim: #c7d6ec;
    --text-faint: #9cb0cf;
    --accent: #7c9eff;
    --accent-2: #a9bfff;
    --ok: #5fd3a2;
    --warn: #f2c35c;
    --info: #7c9eff;
    --sidebar-w: 300px;
    --font:
        'Noto Sans JP', -apple-system, BlinkMacSystemFont, 'Segoe UI',
        'Hiragino Kaku Gothic ProN', 'Yu Gothic', Meiryo, sans-serif;
    --mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
    overflow-x: hidden;
    scroll-padding-top: 24px;
}
body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family: var(--font);
    font-size: 16px;
    line-height: 1.85;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}
a {
    color: var(--accent-2);
    text-decoration: none;
    border-bottom: 1px solid rgba(124, 158, 255, 0.35);
    overflow-wrap: anywhere;
}
a:hover {
    color: #fff;
    border-bottom-color: var(--accent);
}
.layout {
    display: block;
}
/* sidebar */
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--sidebar-w);
    background: #050d18;
    border-right: 1px solid var(--line);
    overflow-y: auto;
    padding: 24px 14px 40px;
    z-index: 50;
}
.sidebar .brand {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 0 10px 18px;
    border-bottom: 1px solid var(--line);
    margin-bottom: 14px;
}
.sidebar .brand .dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--accent);
    box-shadow: 0 0 12px var(--accent);
}
.sidebar .brand span {
    font-size: 12px;
    letter-spacing: 0.08em;
    color: var(--text-faint);
    font-weight: 700;
    text-transform: uppercase;
}
.sidebar ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.sidebar li {
    margin: 0;
}
.sidebar a {
    display: block;
    border: 0;
    color: var(--text-dim);
    font-size: 13.5px;
    line-height: 1.55;
    padding: 7px 10px;
    border-radius: 8px;
    border-left: 2px solid transparent;
}
.sidebar a:hover {
    background: var(--bg-2);
    color: #fff;
}
.sidebar a.active {
    background: rgba(124, 158, 255, 0.14);
    color: #fff;
    border-left-color: var(--accent);
}
.sidebar ul ul {
    margin: 2px 0 6px 12px;
}
.sidebar a.sub {
    font-size: 12.5px;
    color: var(--text-faint);
    padding: 4px 10px;
}
.sidebar a.sub.active {
    color: #fff;
}
.nav-toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 60;
    background: var(--bg-3);
    color: #fff;
    border: 1px solid var(--line-2);
    border-radius: 10px;
    padding: 8px 12px;
    font: inherit;
    font-size: 14px;
    cursor: pointer;
}
.scrim {
    display: none;
}
/* main */
.main {
    margin-left: var(--sidebar-w);
    padding: 0 56px 80px;
}
.hero {
    position: relative;
    padding: 64px 0 36px;
    border-bottom: 1px solid var(--line);
    margin-bottom: 12px;
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    right: -120px;
    top: -160px;
    width: 560px;
    height: 560px;
    background: radial-gradient(
        circle,
        rgba(124, 158, 255, 0.22),
        rgba(124, 158, 255, 0) 65%
    );
    pointer-events: none;
}
.eyebrow {
    display: inline-block;
    padding: 5px 14px;
    border: 1px solid var(--line-2);
    border-radius: 999px;
    background: rgba(124, 158, 255, 0.1);
    color: var(--accent-2);
    font-size: 12.5px;
    font-weight: 700;
    letter-spacing: 0.06em;
    margin-bottom: 18px;
}
.hero-title {
    margin: 0 0 10px;
    font-size: 28px;
    line-height: 1.35;
    font-weight: 800;
    color: #fff;
    position: relative;
}
.hero-sub {
    margin: 0 0 26px;
    font-size: 17px;
    color: var(--text-dim);
    position: relative;
}
.hero-meta {
    display: flex;
    flex-wrap: wrap;
    position: relative;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: rgba(11, 26, 46, 0.7);
}
.hero-meta .m {
    padding: 14px 22px;
    border-right: 1px solid var(--line);
    min-width: 0;
    flex: 1 1 200px;
}
.hero-meta .m:last-child {
    border-right: 0;
}
.hero-meta .k {
    display: block;
    font-size: 11px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-faint);
    font-weight: 700;
}
.hero-meta .v {
    display: block;
    font-size: 14.5px;
    color: var(--text);
    overflow-wrap: anywhere;
}
.hero-note {
    position: relative;
    margin-top: 20px;
}
/* headings */
.main h2 {
    font-size: 23px;
    font-weight: 800;
    color: #fff;
    margin: 56px 0 18px;
    padding: 0 0 12px;
    border-bottom: 1px solid var(--line);
    line-height: 1.4;
}
.main h3 {
    font-size: 18.5px;
    font-weight: 700;
    color: var(--accent-2);
    margin: 34px 0 12px;
    line-height: 1.5;
    padding-left: 12px;
    border-left: 3px solid var(--accent);
}
.main p {
    margin: 0 0 16px;
    color: var(--text);
}
.main strong {
    color: #fff;
    font-weight: 700;
}
.main ul,
.main ol {
    padding-left: 1.4em;
    margin: 0 0 16px;
}
.main li {
    margin: 4px 0;
}
.main code:not(pre code) {
    font-family: var(--mono);
    font-size: 0.9em;
    background: var(--bg-3);
    border: 1px solid var(--line);
    padding: 1px 6px;
    border-radius: 6px;
    overflow-wrap: anywhere;
    word-break: break-word;
}
/* tables */
.table-scroll {
    overflow-x: auto;
    margin: 0 0 24px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--bg-2);
}
.main table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
    line-height: 1.7;
}
.main th {
    background: var(--bg-3);
    color: #fff;
    text-align: left;
    font-weight: 700;
    padding: 11px 16px;
    border-bottom: 1px solid var(--line-2);
    white-space: nowrap;
}
.main td {
    padding: 11px 16px;
    border-bottom: 1px solid var(--line);
    color: var(--text-dim);
    vertical-align: top;
}
.main tr:last-child td {
    border-bottom: 0;
}
.main tbody tr:hover td {
    background: rgba(124, 158, 255, 0.05);
}
.main td strong {
    color: #fff;
}
.main td a {
    word-break: break-all;
}
/* callouts */
.callout {
    display: flex;
    gap: 14px;
    margin: 0 0 22px;
    padding: 16px 20px;
    border: 1px solid var(--line-2);
    border-left-width: 4px;
    border-radius: 12px;
    background: var(--bg-2);
}
.callout-icon {
    font-size: 20px;
    line-height: 1.6;
    flex: 0 0 auto;
}
.callout-body {
    min-width: 0;
    flex: 1;
}
.callout-body p:last-child {
    margin-bottom: 0;
}
.callout-practice {
    border-left-color: var(--accent);
    background: rgba(124, 158, 255, 0.08);
}
.callout-warn {
    border-left-color: var(--warn);
    background: rgba(242, 195, 92, 0.08);
}
.callout-note {
    border-left-color: var(--ok);
    background: rgba(95, 211, 162, 0.07);
}
.hero-note.callout {
    margin-bottom: 0;
}
/* mermaid */
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 22px 18px;
    margin: 0 0 26px;
    background: linear-gradient(180deg, #0a1626, #08121f);
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
}
.mermaid-diagram p {
    color: inherit;
    margin: 0;
}
.mermaid-diagram .edgeLabel,
.mermaid-diagram .edgeLabel p,
.mermaid-diagram .edgeLabel span {
    color: #dbe7ff !important;
    background-color: #0b1a2e !important;
}
.mermaid-diagram .edgeLabel rect {
    fill: #0b1a2e !important;
    opacity: 1;
}
.mermaid-diagram .nodeLabel,
.mermaid-diagram .nodeLabel p {
    margin: 0;
}
/* checklist */
.checklist-card {
    border: 1px solid var(--line-2);
    border-radius: 14px;
    background: var(--bg-2);
    padding: 18px 22px;
    margin: 0 0 24px;
}
.checklist-progress {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 12px;
}
.cp-label {
    font-size: 12px;
    letter-spacing: 0.1em;
    color: var(--text-faint);
    font-weight: 700;
}
.cp-bar {
    flex: 1;
    height: 8px;
    border-radius: 99px;
    background: var(--bg-3);
    overflow: hidden;
}
.cp-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--accent), var(--ok));
    transition: width 0.25s;
}
.cp-count {
    font-size: 13.5px;
    color: var(--text-dim);
    white-space: nowrap;
}
.checklist {
    list-style: none;
    padding: 0;
    margin: 0;
}
.checklist li {
    padding: 9px 0;
    border-bottom: 1px dashed var(--line);
}
.checklist li:last-child {
    border-bottom: 0;
}
.checklist label,
.checklist li {
    cursor: pointer;
}
.checklist input {
    accent-color: var(--accent);
    width: 17px;
    height: 17px;
    vertical-align: -3px;
    margin-right: 10px;
}
.checklist li.done {
    color: var(--text-faint);
    text-decoration: line-through;
    text-decoration-color: rgba(156, 176, 207, 0.5);
}
.page-footer {
    margin-top: 64px;
    padding-top: 22px;
    border-top: 1px solid var(--line);
    color: var(--text-faint);
    font-size: 13.5px;
}
@media (max-width: 980px) {
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.25s;
        box-shadow: 0 0 40px rgba(0, 0, 0, 0.6);
    }
    .sidebar.open {
        transform: none;
    }
    .nav-toggle {
        display: block;
    }
    .scrim.show {
        display: block;
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.55);
        z-index: 40;
    }
    .main {
        margin-left: 0;
        padding: 0 18px 60px;
    }
    .hero {
        padding-top: 70px;
    }
    .hero-title {
        font-size: 23px;
    }
    .hero-meta .m {
        border-right: 0;
        border-bottom: 1px solid var(--line);
    }
    .hero-meta .m:last-child {
        border-bottom: 0;
    }
}
